var DATA = {"mode": "health", "smart": {"05": 100, "A3": 100, "AD": 100}};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="health"){
  var a=DATA.smart,k=Object.keys(a),w=k[0],i;
  for(i=1;i<k.length;i++){if(a[k[i]]<a[w])w=k[i];}
  show("Worst SMART attribute",w+" at "+a[w]+"% remaining");
  show("Verdict",a[w]>80?"GOOD":(a[w]>50?"WORN - plan replacement":"REPLACE NOW"));
}else if(m==="smart"){
  var a2=DATA.smart,k2=Object.keys(a2);
  console.log("SMART attributes ("+k2.length+"):");
  k2.forEach(function(k){console.log("  "+k+": "+a2[k]+"% remaining");});
}else if(m==="temp"){
  show("Current temp",DATA.temp_c+" C");
  show("Warning threshold",DATA.warn_c+" C");
  show("Headroom",(DATA.warn_c-DATA.temp_c)+" C");
  show("Status",DATA.temp_c<DATA.warn_c?"OK":"THROTTLING RISK");
}else if(m==="firmware"){
  show("Installed",DATA.cur);show("Latest",DATA.latest);
  show("Action",DATA.cur===DATA.latest?"up to date":"UPDATE AVAILABLE - back up first, keep power stable");
}else if(m==="bench"){
  show("Sequential read",DATA.seq_read+" MB/s ("+(Math.round(DATA.seq_read/1024*10)/10)+" GB/s)");
  show("Sequential write",DATA.seq_write+" MB/s");
  show("Random 4K read",DATA.rand4k+" IOPS");
  show("PCIe link",DATA.pcie);
}else if(m==="op"){
  show("Over-provisioning",DATA.op_pct+"% reserved");
  show("User addressable",(Math.round((100-DATA.op_pct)*10)/10)+"% of NAND");
  show("Benefit","steadier write speed + longer endurance");
}else if(m==="diag"){
  show("Scan type",DATA.scan);
  show("Blocks checked",DATA.blocks);
  show("Bad blocks",DATA.bad);
  show("Result",DATA.bad===0?"PASS - no errors":"FAIL - back up and replace");
}else if(m==="erase"){
  show("Method",DATA.method);
  show("Passes",DATA.passes);
  show("Controller verification",DATA.verify);
  show("Data unrecoverable",DATA.verify==="clean"?"YES":"NO");
}else if(m==="migrate"){
  show("Source",DATA.src);show("Target",DATA.dst);
  show("Moved",DATA.gb+" GB in "+DATA.min+" min");
  show("Rate",(Math.round(DATA.gb/DATA.min*10)/10)+" GB/min");
}else if(m==="encrypt"){
  show("Standard",DATA.std);
  show("State",DATA.on?"ENABLED":"OFF");
  show("Note","hardware AES - no CPU overhead when on");
}else if(m==="tbw"){
  show("Written",DATA.written+" TBW of "+DATA.rated+" TBW rated");
  show("Endurance used",(Math.round(DATA.written/DATA.rated*10000)/100)+"%");
  show("Remaining",(Math.round((DATA.rated-DATA.written)*10)/10)+" TBW");
}else if(m==="workflow"){
  console.log("Bench workflow:");
  DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
console.log("DEMO_OK");

